 WHERE car01_company_id = #{companyId}
   AND car01_car_type LIKE #{carType}
   AND (COALESCE(car01_car_no,' ')||COALESCE(car01_car_nm,' ')||COALESCE(car01_car_info,' ')||COALESCE(car01_note,' ') LIKE #{searchText})
