UPDATE car01_info
   SET car01_car_type     = #{req.carType},
       car01_car_no       = #{req.carNo},
       car01_car_nm       = #{req.carNm},
       car01_car_info     = #{req.carInfo},
       car01_note         = #{req.note},
       car01_init_mileage = #{req.initMileage}
 WHERE car01_info_id    = #{req.infoId}
   AND car01_company_id = #{companyId}

