SELECT 
  FROM car01_info
 WHERE car01_company_id = #{companyId}
   AND car01_car_type LIKE #{carType}
   AND #{personId} IN (
           SELECT car02_person_id
             FROM car02_user
            WHERE car02_info_id = car01_info_id
              AND to_char(COALESCE(car02_start_date,'9999-12-31'),'YYYY.MM') <= #{stdMonth}
              AND to_char(COALESCE(car02_close_date,'9999-12-31'), 'YYYY.MM') >= #{stdMonth}
       )
   AND (COALESCE(car01_car_no,' ')||COALESCE(car01_car_nm,' ')||COALESCE(car01_car_info,' ')||COALESCE(car01_note,' ') LIKE #{searchText})

